mapper.select:
SELECT NVL(COUNT(*), 0)
FROM RECIPE R
LEFT OUTER JOIN MEMBER M ON R.AUTHOR_ID = M.MEMBER_ID

    R.SOURCE_TYPE = 'MEMBER' AND R.STATUS = 0 AND R.DELETED_AT IS NULL

        AND 


        AND R.RECIPE_ID IN (
            SELECT RECIPE_ID FROM RECIPE_CATEGORY
            WHERE CATEGORY_ID = #{categoryId}
        )


        AND R.AUTHOR_ID = #{authorId}

SELECT CATEGORY_ID FROM RECIPE_CATEGORY
WHERE RECIPE_ID = #{recipeId}
ORDER BY CATEGORY_ID

SELECT TAG_ID FROM RECIPE_TAG
WHERE RECIPE_ID = #{recipeId}
ORDER BY TAG_ID
